import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, SRGBColorSpace } = ctx.THREE;

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const C = {
    background: colors.background || '#0b0b10',
    surface: colors.surface || '#14141a',
    ink: colors.ink || '#16161d',
    paper: colors.paper || '#e8ecf2',
    accent: colors.accent || '#ff2a38',
  };
  const stops = colors.gradientStops || [{ at: 0, hex: C.background }, { at: 1, hex: C.surface }];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') || { text: 'Inside the atelier' };
  const captionItems = items.filter((i) => i.role === 'caption');
  const captionTexts = captionItems.length
    ? captionItems.map((i) => i.text)
    : ['DIAL ROOM', 'ESCAPEMENT BENCH', 'CNC HALL', 'FINISHING LAB', 'ARCHIVE VAULT', 'ASSEMBLY LINE ONE'];

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- Backdrop stage (gradient, never void) ----------
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(color(stops[0].hex), color(stops[stops.length - 1].hex), smoothstep(float(0.0), float(1.0), uv().y));
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, -0.25, -2.5);
  group.add(bg);
  disposables.push(bgGeo, bgMat);

  // Faint machined rail behind the column (depth plane 2)
  const railGeo = new BoxGeometry(2.2, 5.6, 0.04);
  const railMat = new MeshStandardNodeMaterial({ color: C.ink, roughness: 0.55, metalness: 0.5 });
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0.9, 0, -1.2);
  group.add(rail);
  disposables.push(railGeo, railMat);

  // ---------- Local lights (scene supplies ambient 0.6 + key 1.2) ----------
  const rim = new DirectionalLight(C.accent, 0.7);
  rim.position.set(-3, 1.5, -2);
  group.add(rim);
  const fill = new DirectionalLight(C.paper, 0.5);
  fill.position.set(2.5, -1, 3);
  group.add(fill);

  // ---------- Headline + accent rule (foreground plane) ----------
  const headline = ctx.fontAtlas.createText(String(headlineItem.text), {
    fontSize: 68, color: C.paper, align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0.1);
  group.add(headline);

  const ruleGeo = new BoxGeometry(0.9, 0.03, 0.03);
  const ruleMat = new MeshStandardNodeMaterial({
    color: C.accent, roughness: 0.5, metalness: 0.3,
    emissive: C.accent, emissiveIntensity: 0.6,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.15, 1.55, 0.1);
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------- Loop column of plates ----------
  const PLATE_W = 1.9, PLATE_H = 1.2, PITCH = 1.5, LOOP = 9.0, COUNT = 6;
  const COL_X = 0.9;

  const column = new Group();
  column.position.set(COL_X, 0, 0);
  group.add(column);

  // subtle TSL vignette factor plane baked over each image
  const plates = [];
  const crops = [
    { ox: 0.0, oy: 0.0, rx: 1.0, ry: 1.0 },
    { ox: 0.05, oy: 0.1, rx: 0.85, ry: 0.85 },
    { ox: 0.15, oy: 0.0, rx: 0.8, ry: 0.9 },
    { ox: 0.0, oy: 0.2, rx: 0.9, ry: 0.75 },
    { ox: 0.2, oy: 0.15, rx: 0.75, ry: 0.8 },
    { ox: 0.1, oy: 0.05, rx: 0.88, ry: 0.88 },
  ];

  for (let i = 0; i < COUNT; i++) {
    const plate = new Group();

    // machined ink bevel frame
    const frameGeo = new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.06);
    const frameMat = new MeshStandardNodeMaterial({ color: C.ink, roughness: 0.5, metalness: 0.5 });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    plate.add(frame);
    disposables.push(frameGeo, frameMat);

    // photograph surface — starts as lit surface tone, never black void
    const imgGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const imgMat = new MeshPhysicalNodeMaterial({
      color: C.surface, roughness: 0.6, metalness: 0.1, clearcoat: 0.1,
    });
    // baked-feel vignette via TSL edge darkening
    const d = uv().sub(vec2(0.5, 0.5)).length();
    imgMat.colorNode = null; // map drives color; vignette applied via emissive-free ao style below
    imgMat.aoNode = smoothstep(float(0.75), float(0.35), d).mul(0.35).add(0.65);
    const img = new Mesh(imgGeo, imgMat);
    img.position.z = 0.02;
    plate.add(img);
    disposables.push(imgGeo, imgMat);

    // accent focus strip on left edge
    const stripGeo = new BoxGeometry(0.03, PLATE_H, 0.03);
    const stripMat = new MeshStandardNodeMaterial({
      color: C.accent, emissive: C.accent, emissiveIntensity: 0.0,
      roughness: 0.5, metalness: 0.2, transparent: true, opacity: 0.0,
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-(PLATE_W / 2) - 0.045, 0, 0.02);
    plate.add(strip);
    disposables.push(stripGeo, stripMat);

    // caption at world x = -1.6 (local -2.5 relative to column)
    const caption = ctx.fontAtlas.createText(String(captionTexts[i % captionTexts.length]), {
      fontSize: 18, color: C.paper, align: 'left', letterSpacingPx: 1.6,
    });
    caption.position.set(-2.5, 0, 0.08);
    setTextOpacity(caption, 0);
    plate.add(caption);

    column.add(plate);
    plates.push({ plate, img, imgMat, strip, stripMat, caption, focused: false });
  }

  function setTextOpacity(obj, v) {
    obj.traverse((c) => {
      if (c.material) {
        c.material.transparent = true;
        c.material.opacity = v;
      }
    });
  }

  // load base texture + distinct crop variants
  ctx.textureLoader.loadTexture(config.imageUrl || '/prism-mock/home/nodes/feature-card.png').then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    plates.forEach((p, i) => {
      const t = tex.clone();
      const c = crops[i % crops.length];
      t.offset.set(c.ox, c.oy);
      t.repeat.set(c.rx, c.ry);
      t.needsUpdate = true;
      p.imgMat.map = t;
      p.imgMat.color.set('#ffffff');
      p.imgMat.needsUpdate = true;
      disposables.push(t);
    });
  }).catch(() => {});

  // ---------- Scroll physics: weighted inertia, damping 0.12 ----------
  const scroll = { current: 0, target: 0 };
  let focusedIdx = -1;

  const wrapY = (y) => ((y % LOOP) + LOOP + LOOP / 2) % LOOP - LOOP / 2;

  function focus(idx) {
    if (idx === focusedIdx) return;
    if (focusedIdx >= 0) {
      const prev = plates[focusedIdx];
      const tlOut = gsap.timeline();
      tlOut.to(prev.plate.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.35, ease: 'power2.out' }, 0);
      tlOut.to(prev.stripMat, { opacity: 0, emissiveIntensity: 0, duration: 0.3, ease: 'power2.out' }, 0);
      const po = { v: 1 };
      tlOut.to(po, { v: 0, duration: 0.3, ease: 'power2.out', onUpdate: () => setTextOpacity(prev.caption, po.v) }, 0);
      timelines.push(tlOut);
    }
    focusedIdx = idx;
    const cur = plates[idx];
    const tlIn = gsap.timeline();
    tlIn.to(cur.plate.scale, { x: 1.06, y: 1.06, z: 1.06, duration: 0.35, ease: 'power2.out' }, 0);
    tlIn.to(cur.stripMat, { opacity: 1, emissiveIntensity: 1.4, duration: 0.35, ease: 'power2.out' }, 0);
    const co = { v: 0 };
    tlIn.to(co, { v: 1, duration: 0.4, ease: 'power2.out', onUpdate: () => setTextOpacity(cur.caption, co.v) }, 0.08);
    timelines.push(tlIn);
  }

  let idleT = 0;
  function tick(_, deltaMS) {
    const dt = Math.min(deltaMS / 1000, 0.05);
    idleT += dt;
    if (idleT > 2.5) scroll.target += dt * 0.12; // single slow idle drift
    scroll.current += (scroll.target - scroll.current) * 0.12;

    let bestIdx = 0, bestDist = Infinity;
    plates.forEach((p, i) => {
      const y = wrapY(i * PITCH + scroll.current);
      p.plate.position.y = y;
      // recede near loop seam so wrap never pops
      const edge = Math.max(0, Math.min(1, (4.4 - Math.abs(y)) / 1.2));
      p.plate.position.z = -0.4 * (1 - edge);
      const ad = Math.abs(y);
      if (ad < bestDist) { bestDist = ad; bestIdx = i; }
    });
    if (bestDist < 0.9) focus(bestIdx);
  }
  gsap.ticker.add(tick);

  // ---------- Entrance: rise-in + weighted settle ----------
  group.position.y -= 0.4;
  const entrance = gsap.timeline();
  entrance.to(group.position, { y: group.position.y + 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  entrance.fromTo(column.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.2);
  timelines.push(entrance);

  // ---------- Cinematic primitives from config ----------
  for (const prim of config.cinematicPrimitives || []) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      primHandles.push(ctx.primitives[prim.name](group, prim.params || {}));
    }
  }

  // ---------- Handlers ----------
  group.userData.handlers = {
    scroll: (e) => {
      idleT = 0;
      if (e && typeof e.progress === 'number') {
        scroll.target = e.progress * LOOP;
      } else {
        const d = (e && (e.deltaY ?? e.delta ?? 0)) || 0;
        scroll.target += d * 0.0015 * 1.5;
      }
    },
  };

  group.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d && d.dispose && d.dispose());
  };

  return group;
}
